func (a *App) serveHTTP(w http.ResponseWriter,r *http.Request){
 a.mu.Lock();defer a.mu.Unlock()
 if r.URL.Path=="/ready" {write(w,200,map[string]string{"status":"ready"});return}
 if r.URL.Path=="/"||r.URL.Path=="/index.html" {http.ServeFile(w,r,"web/index.html");return}
 if !strings.HasPrefix(r.URL.Path,"/api/"){http.NotFound(w,r);return}
