 if r.URL.Path=="/api/events" {u,_,ok:=a.user(r);if !ok{fail(w,401,"unauthorized","Authentication is required");return}; _=u; write(w,200,map[string]any{"data":map[string]any{"events":[]any{},"cursor":len(a.state.Audit)}});return}
