}
func (a *App) login(w http.ResponseWriter,r *http.Request){if r.Method!="POST"{fail(w,405,"method_not_allowed","Use POST");return};v,e:=body(r);if e!=nil||str(v,"username")==""||str(v,"password")==""{fail(w,400,"invalid_json","Username and password are required");return};for _,u:=range a.state.Users{if u.Username==str(v,"username")&&u.Password==str(v,"password")&&u.Active{t:=id(); role:=u.Roles[0];a.state.Sessions[t]=Session{u.ID,role,now()};a.audit(&u,"sign_in","user",u.ID,"success",nil);a.save();write(w,200,map[string]any{"data":map[string]any{"sessionToken":t,"userId":u.ID,"roles":u.Roles,"activeRole":role}});return}};fail(w,401,"invalid_credentials","Invalid username or password")}
func (a *App) bootstrap(w http.ResponseWriter,r *http.Request){u,se,ok:=a.user(r);if !ok{fail(w,401,"unauthorized","Authentication is required");return}; sam:=[]any{};for _,s:=range a.state.Samples {if se.Role=="requester"&&s.RequesterID!=u.ID{continue};sam=append(sam,sampleView(s))}; ops:=map[string]any{"samples":[]any{},"workers":[]any{},"locations":[]any{},"connections":[]any{},"routes":[]any{},"handoffs":[]any{},"delays":[]any{},"exceptions":[]any{},"assignmentCountSpread":0,"ineligibleAssignmentCount":0};for _,s:=range a.state.Samples {ops["samples"]=append(ops["samples"].([]any),map[string]any{"sampleId":s.ID,"status":s.Status,"locationStale":s.LocationAt=="","currentHolderId":s.HolderID})};for _,l:=range a.state.Locations{ops["locations"]=append(ops["locations"].([]any),l)};for _,c:=range a.state.Connections{ops["connections"]=append(ops["connections"].([]any),c)};for _,u:=range a.state.Users{if workerRole(se.Role)||se.Role=="dispatcher"||se.Role=="administrator"{ops["workers"]=append(ops["workers"].([]any),map[string]any{"workerId":u.ID,"fullName":u.FullName,"roles":u.Roles,"available":u.Available,"status":map[bool]string{true:"available",false:"unavailable"}[u.Available],"capacityUnits":u.CapacityUnits,"assignmentCount":0,"locationStale":true})}};write(w,200,map[string]any{"data":map[string]any{"user":map[string]any{"userId":u.ID,"username":u.Username,"fullName":u.FullName,"roles":u.Roles,"activeRole":se.Role,"roleSelectionRequired":false},"serverTime":now(),"requesterSamples":sam,"operations":ops}})}
func (a *App) readSample(w http.ResponseWriter,r *http.Request,sid string){u,se,ok:=a.user(r);if !ok{fail(w,401,"unauthorized","Authentication is required");return};s,ok:=a.state.Samples[sid];if !ok{fail(w,404,"not_found","Sample not found");return};if se.Role=="requester"&&s.RequesterID!=u.ID{fail(w,403,"forbidden","Sample belongs to another requester");return};write(w,200,map[string]any{"data":sampleView(s)})}
