func userView(u User)map[string]any{return map[string]any{"userId":u.ID,"username":u.Username,"email":u.Email,"fullName":u.FullName,"phone":u.Phone,"roles":u.Roles,"qualifications":u.Qualifications,"certifications":u.Certifications,"active":u.Active}}
