{"command":"create","path":"/workspace/web/index.html","security_risk":"MEDIUM","summary":"Create accessible single-page operations dashboard frontend","file_text":"<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SampleFlow | Lab logistics</title><style>
