</style></head><body><main id="app" aria-live="polite"></main><script>
const api=(path,method='GET',body)=>fetch('/api/'+path,{method,headers:{'Content-Type':'application/json',...(localStorage.token?{Authorization:'Bearer '+localStorage.token}:{})},body:body?JSON.stringify(body):undefined}).then(async r=>{let j=await r.json();if(!r.ok)throw new Error(j.error||'Request failed');return j.data});
let boot=null,view='dashboard';const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));const date=()=>new Date().toISOString();
function login(){document.title='Sign in | SampleFlow';$('#app').innerHTML=`<section class="login"><form class="login-card" aria-label="Sign in"><div class="brand"><b class="mark">✚</b> SampleFlow</div><p class="sub">Secure coordination for clinical sample pickup, custody, and laboratory delivery.</p><div id="err"></div><label class="field">Username<input name="username" autocomplete="username" required placeholder="Administrator username"></label><label class="field">Password<input name="password" type="password" autocomplete="current-password" required placeholder="Password"></label><button type="submit" style="width:100%;margin-top:8px">Sign in</button><p class="muted" style="font-size:12px">Use the administrator credentials supplied at startup.</p></form></section>`;$('.login-card').onsubmit=async e=>{e.preventDefault();try{let d=await api('authenticate-user','POST',Object.fromEntries(new FormData(e.target)));localStorage.token=d.sessionToken;load()}catch(x){$('#err').innerHTML='<div class="error" role="alert">Invalid username or password.</div>'}}}
async function load(){try{boot=await api('ui/bootstrap');render()}catch(e){localStorage.removeItem('token');login()}}
function shell(content){let u=boot.user;return `<div class="shell"><aside class="side"><div class="brand"><b class="mark">✚</b> SampleFlow</div>${[['dashboard','▦','Operations'],['work','✓','My work'],['request','＋','New request'],['tracking','⌖','Sample tracking'],['audit','◷','Audit trail']].map(x=>`<button class="nav ${view==x[0]?'active':''}" data-view="${x[0]}"><span>${x[1]}</span>${x[2]}</button>`).join('')}<div class="side-foot"><div class="label">Signed in</div><b>${esc(u.fullName||u.username)}</b><br><button class="nav" id="signout">↪ Sign out</button></div></aside><section class="main"><header class="top"><div><h1>${view==='dashboard'?'Operations overview':view==='work'?'My work':view==='request'?'Create collection request':view==='tracking'?'Sample tracking':'Audit trail'}</h1><p>${view==='dashboard'?'A live view of network health and sample flow.':'Role-scoped access and durable custody records.'}</p></div><div class="context"><label for="role" class="muted">Working as</label><select id="role" aria-label="Active role">${u.roles.map(r=>`<option ${r===u.activeRole?'selected':''}>${r.replaceAll('_',' ')}</option>`).join('')}</select></div></header>${content}</section></div>`}
function dashboard(){let o=boot.operations||{},s=o.samples||[],w=o.workers||[];return shell(`<section class="cards"><div class="card"><div class="label">Active samples</div><div class="metric">${s.length}</div><span class="muted">in the network</span></div><div class="card"><div class="label">Available workers</div><div class="metric">${w.filter(x=>x.available).length}</div><span class="muted">ready for assignments</span></div><div class="card"><div class="label">Open exceptions</div><div class="metric">${(o.exceptions||[]).length}</div><span class="muted">need attention</span></div><div class="card"><div class="label">Network locations</div><div class="metric">${(o.locations||[]).length}</div><span class="muted">configured nodes and labs</span></div></section><section class="two"><article class="panel"><h2>Live sample monitor</h2>${s.length?`<table class="table"><thead><tr><th>Sample</th><th>Status</th><th>Custodian</th><th>Location freshness</th></tr></thead><tbody>${s.map(x=>`<tr><td><button class="secondary sample" data-id="${x.sampleId}">${x.sampleId.slice(0,8)}</button></td><td><span class="pill ${x.status==='exception'?'red':''}">${esc(x.status)}</span></td><td>${esc(x.currentHolderId||'Awaiting collection')}</td><td>${x.locationStale?'<span class="pill red">Stale</span>':'<span class="pill">Current</span>'}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">No samples are in the network yet.</p>'}</article><article class="panel"><h2>Network map</h2><div class="map" aria-label="Local network map"><i class="dot" style="left:30%;top:36%"></i><i class="dot" style="left:63%;top:61%;background:#0a9b8a"></i><i class="dot" style="left:72%;top:24%;background:#d84856"></i></div><p class="muted">Local network locations and worker updates appear here. Map tiles remain local to this deployment.</p></article></section>`)}
function request(){let typeHint='Enter a configured sample type ID. Default sample types are created on reset.';return shell(`<article class="panel"><h2>Serviceability & request details</h2><p class="muted">This check is a dry run: it does not reserve capacity or create work.</p><form id="req"><div class="form-grid"><label class="field">Sample type ID<input name="sampleTypeId" required placeholder="UUID" aria-describedby="type-help"></label><span id="type-help" class="muted">${typeHint}</span><label class="field">Origin type<select name="originType"><option value="home">Patient home</option><option value="clinic">Clinic</option><option value="node">Network node</option></select></label><label class="field">Latitude<input name="latitude" type="number" step="any" required value="51.5074"></label><label class="field">Longitude<input name="longitude" type="number" step="any" required value="-0.1278"></label><label class="field">Collection earliest<input name="earliestCollectionAt" type="datetime-local"></label><label class="field">Collection latest<input name="latestCollectionAt" type="datetime-local"></label><label class="field">Delivery deadline<input name="deliveryDeadline" type="datetime-local" required></label><label class="field">Container type<input name="containerType" required value="standard"></label><label class="field">Minimum temperature °C<input name="temperatureMinC" type="number" value="2" required></label><label class="field">Maximum temperature °C<input name="temperatureMaxC" type="number" value="25" required></label></div><div id="reqout"></div><div class="actions"><button type="button" id="check">Check serviceability</button><button type="submit" class="secondary">Create collection request</button></div></form></article>`)}
function work(){let assignments=[];let samples=boot.requesterSamples||[];return shell(`<section class="two"><article class="panel"><h2>Current work</h2><div class="work">${assignments.length?assignments:'<p class="empty">No currently offered or accepted assignments.</p>'}</div></article><article class="panel"><h2>Completed work</h2><p class="empty">Completed work is retained in your timeline.</p></article></section><article class="panel" style="margin-top:18px"><h2>My responsible samples</h2>${samples.length?`<table class="table"><thead><tr><th>Sample</th><th>Status</th><th>Deadline</th><th></th></tr></thead><tbody>${samples.map(s=>`<tr><td>${s.sampleId.slice(0,8)}</td><td><span class="pill">${s.state.status}</span></td><td>${new Date(s.deliveryDeadline).toLocaleString()}</td><td><button class="secondary sample" data-id="${s.sampleId}">View status timeline</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">Your role has no samples to display.</p>'}</article>`)}
function tracking(){let samples=boot.requesterSamples||[];return shell(`<article class="panel"><h2>Locate a sample</h2><label class="field">Sample ID<input id="lookup" placeholder="Enter a sample UUID"></label><button id="find">View sample</button><div id="track-result"></div></article><article class="panel" style="margin-top:18px"><h2>Recent samples</h2>${samples.map(s=>`<button class="secondary sample" data-id="${s.sampleId}" style="margin:3px">${s.sampleId.slice(0,8)} · ${s.state.status}</button>`).join('')||'<p class="empty">No samples visible under this role.</p>'}</article>`)}
function audit(){return shell(`<article class="panel"><h2>Search durable audit history</h2><div class="actions"><input id="auditq" placeholder="Search actions, entities, or outcomes" style="flex:1;padding:9px;border:1px solid var(--line);border-radius:7px"><button id="search">Search</button></div><div id="audit-result" class="empty">Search sign-ins, offers, custody records, configuration changes, and exceptions.</div></article>`)}
function render(){let content=view==='dashboard'?dashboard():view==='request'?request():view==='work'?work():view==='tracking'?tracking():audit();$('#app').innerHTML=content;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$('#signout').onclick=()=>{localStorage.removeItem('token');login()};$('#role').onchange=async e=>{await api('select-active-role','POST',{role:e.target.value.replaceAll(' ','_')});load()};document.querySelectorAll('.sample').forEach(b=>b.onclick=()=>showSample(b.dataset.id));if(view==='request')bindRequest();if(view==='tracking')$('#find').onclick=()=>showSample($('#lookup').value);if(view==='audit')$('#search').onclick=searchAudit()}
function toISO(x){return x?new Date(x).toISOString():date()}function payload(form){let d=Object.fromEntries(new FormData(form));return {...d,origin:{latitude:+d.latitude,longitude:+d.longitude},requestedAt:date(),deliveryDeadline:toISO(d.deliveryDeadline),earliestCollectionAt:toISO(d.earliestCollectionAt),latestCollectionAt:toISO(d.latestCollectionAt),temperatureMinC:+d.temperatureMinC,temperatureMaxC:+d.temperatureMaxC}}
function bindRequest(){let f=$('#req');$('#check').onclick=async()=>{try{let d=await api('check-serviceability','POST',payload(f));$('#reqout').innerHTML=`<p class="${d.serviceable?'pill':'error'}">${d.serviceable?'Serviceable — laboratory '+d.targetLaboratoryId.slice(0,8):'Not serviceable — '+d.reason}</p>`}catch(e){$('#reqout').innerHTML='<p class="error" role="alert">'+esc(e.message)+'</p>'}};f.onsubmit=async e=>{e.preventDefault();try{let d=await api('create-collection-request','POST',payload(f));$('#reqout').innerHTML='<p class="pill">Request '+d.requestId.slice(0,8)+' created. Serviceability: '+d.serviceability+'</p>';load()}catch(x){$('#reqout').innerHTML='<p class="error" role="alert">'+esc(x.message)+'</p>'}}}
async function showSample(id){try{let s=await api('read-sample-state/'+id);view='tracking';render();let t=(s.timeline||[]).map(x=>`<div class="event"><b>${esc(x.status)}</b><br><span class="muted">${new Date(x.occurredAt).toLocaleString()} · ${esc(x.detail||'')}</span></div>`).join('');setTimeout(()=>{$('#track-result').innerHTML=`<section class="panel" style="margin-top:18px"><h2>Sample ${esc(s.sampleId)}</h2><div class="cards"><div><div class="label">Current status</div><b>${esc(s.state.status)}</b></div><div><div class="label">Current custodian</div><b>${esc(s.currentHolderId||'Not yet assigned')}</b></div><div><div class="label">Location freshness</div><b>${s.locationStale?'Stale':'Current'}</b></div><div><div class="label">Route progress</div><b>${(s.activeAssignmentIds||[]).length} assigned leg(s)</b></div></div><div class="timeline">${t||'<div class="event">No status changes recorded.</div>'}</div></section>`},0)}catch(e){$('#track-result').innerHTML='<p class="error" role="alert">'+esc(e.message)+'</p>'}}
function searchAudit(){return async()=>{try{let d=await api('search-audit-trail','POST',{query:$('#auditq').value,limit:100});$('#audit-result').innerHTML=d.entries.length?`<table class="table"><thead><tr><th>Time</th><th>Action</th><th>Entity</th><th>Outcome</th></tr></thead><tbody>${d.entries.map(x=>`<tr><td>${new Date(x.occurredAt).toLocaleString()}</td><td>${esc(x.action)}</td><td>${esc(x.entityType)} ${esc(x.entityId)}</td><td>${x.success?'Success':'Failed'}</td></tr>`).join('')}</tbody></table>`:'No audit records matched.'}catch(e){$('#audit-result').innerHTML='<p class="error">'+esc(e.message)+'</p>'}}}
localStorage.token?load():login();
</script></body></html>"}

