","new_str":"func (a *App) initiateHandoff(w http.ResponseWriter, r *http.Request, v map[string]any) {
	u, _, ok := a.user(r); if !ok { fail(w,401,"unauthorized","Authentication is required"); return }
	s, yes := a.state.Samples[str(v,"sampleId")]; if !yes { fail(w,404,"not_found","Sample not found"); return }
	if !s.Sealed || s.HolderID != u.ID { fail(w,409,"custody_conflict","Only the sealed sample holder can initiate handoff"); return }
	from, fy := a.state.Assignments[str(v,"fromAssignmentId")]; to, ty := a.state.Assignments[str(v,"toAssignmentId")]
	if !fy || !ty || from.SampleID != s.ID || to.SampleID != s.ID || to.WorkerID != str(v,"receiverId") { fail(w,409,"handoff_inactive","Assignments do not form a valid handoff"); return }
	h := Handoff{ID:id(),SampleID:s.ID,SenderID:u.ID,ReceiverID:to.WorkerID,Active:true}; a.state.Handoffs[h.ID]=h; timeline(&s,"handoff_pending","Awaiting both custody confirmations"); a.state.Samples[s.ID]=s; a.audit(u,"initiate_handoff","sample",s.ID,"success",map[string]any{"handoffId":h.ID}); a.save()
	write(w,201,map[string]any{"data":map[string]any{"handoffId":h.ID,"senderId":h.SenderID,"receiverId":h.ReceiverID,"currentHolderId":h.SenderID,"status":"pending"}})
}
func (a *App) listWork(w http.ResponseWriter, r *http.Request, v map[string]any) {
	u,se,ok:=a.user(r); if !ok {fail(w,401,"unauthorized","Authentication is required");return}; role:=str(v,"role"); if role=="" {role=se.Role}; if role!=se.Role {fail(w,403,"forbidden","Work is available only for the selected role");return}
	pending,inprogress,completed:=[]any{},[]any{},[]any{}; for _,x:=range a.state.Assignments {if x.WorkerID!=u.ID||x.Role!=role {continue}; item:=map[string]any{"assignmentId":x.ID,"sampleId":x.SampleID,"status":x.Status,"offeredAt":x.OfferedAt}; if x.Status=="offered" {pending=append(pending,item)} else if x.Status=="completed"||x.Status=="delivered" {completed=append(completed,item)} else {inprogress=append(inprogress,item)}}
	write(w,200,map[string]any{"data":map[string]any{"pending":pending,"inProgress":inprogress,"completed":completed}})
}
func (a *App) readJourney(w http.ResponseWriter, r *http.Request, v map[string]any) {
	u,se,ok:=a.user(r);if !ok{fail(w,401,"unauthorized","Authentication is required");return}; j,yes:=a.state.Journeys[str(v,"journeyId")];if !yes{fail(w,404,"not_found","Journey not found");return}; if se.Role=="requester" {visible:=false;for _,sid:=range j.SampleIDs{if a.state.Samples[sid].RequesterID==u.ID{visible=true}};if !visible{fail(w,403,"forbidden","Journey is not visible to this requester");return}};write(w,200,map[string]any{"data":j})
}
func (a *App) operations(w http.ResponseWriter, r *http.Request) {
